te.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /******************************************************************/ #ifndef _SMU_ATTRIBUTE_H_ #define _SMU_ATTRIBUTE_H_ #include &quot;SmuConfig.h&quot; #include &quot;SmuTokens.h&quot; // pixar includes #include &quot;UsdBrepSuppressPixarWarningsPush.h&quot; // turn off compile warnings for problematic pixar include files # include &lt;pxr/usd/usdShade/materialBindingAPI.h&gt; #include &quot;UsdBrepSuppressPixarWarningsPop.h&quot; // done loading problematic pixar headers - restore compile warnings // SMLib includes #include &quot;SmAttribute.h&quot; #define SmSdfPathAttribute_TYPE (SmFirstUserAttribute_TYPE + 1) #define SmUsdXformAttribute_TYPE (SmFirstUserAttribute_TYPE + 2) // Following are used by USD to store metadata #define SM_AI_MATERIAL_BINDING (SM_AI_USER_1 + 1) // Material binding path used by USD #define SM_AI_BREP_ARRAY (SM_AI_USER_1 + 2) // USD path to associated UsdSolidBrepAPI instance #define SM_AI_XFORM_OP (SM_AI_USER_1 + 3) // USD Xform ops /*******************************************************************/ class SmSdfPathAttribute : public SmAttribute { protected: pxr::SdfPathVector m_sMaterialPaths ; // gwc??? this was once a pointer to a SdfPathVector - see if there was a reason for that. It may have to be a pointer once again. public: // constructor - places a copy of pMaterialPaths into m_pMaterialPaths SMU_EXPORT SmSdfPathAttribute( ULONG lAttributeId, // in : SmAttributeBehaviorType eBehavior, // in : const pxr::SdfPathVector &amp; rMaterialPaths) // in : : SmAttribute(lAttributeId, eBehavior) { m_sMaterialPaths = rMaterialPaths ; } // copy constructor SMU_EXPORT SmSdfPathAttribute( const SmSdfPathAttribute &amp; crOriginal) : SmAttribute(crOriginal.m_lAttributeID, // in : crOriginal.m_eBehavior) // in : { m_sMaterialPaths = crOriginal.m_sMaterialPaths ; } // virtual destructor - required implementation for derived objects SMU_EXPORT virtual ~SmSdfPathAttribute() { } // virtual Copy function - required implementation for derived objects SMU_EXPORT virtual SmAttribute * MakeCopy(const SmContext &amp; crContext) const { return( new (crContext) SmSdfPathAttribute( m_lAttributeID, m_eBehavior, m_sMaterialPaths) ) ; } // Attach Path attribute data to a UsdBrepArraySpecHandle - used when moving data from SMLib -&gt; USD SMU_EXPORT bool AttachAttributeToBrepInstance(const pxr::SdfPrimSpecHandle &amp; crUsdBrepArraySpecHandle, pxr::TfToken &amp; tInstanceName); // Attach Xform attributes to a UsdBrepArraySpecHandle - used when moving data from SMLib -&gt; USD SMU_EXPORT bool AttachAttributeToXformable(const pxr::SdfPrimSpecHandle &amp;crUsdBrepArraySpecHandle); // simple data access SMU_EXPORT pxr::SdfPathVector * GetMaterialPaths() { return &amp;m_sMaterialPaths ; } SMU_EXPORT void SetMaterialPaths(pxr::SdfPathVector &amp; rMaterialPaths) { m_sMaterialPaths = rMaterialPaths; } // Define GetType(), IsKindOf(), and virtual Dump() (Dump needs local implementation) SM_COMMON_FOR_EXPORT(SmSdfPathAttribute, SmAttribute, SmSdfPathAttribute_TYPE, SMU_EXPORT); }; //end class SmSdfPathAttribute /*******************************************************************/ class SmUsdXformAttribute : public SmAttribute { protected: pxr::GfVec3d m_sTranslate ; pxr::GfVec3d m_sScale ; pxr::GfVec3d m_sRotateXYZ ; pxr::GfVec3d m_sRotateXZY ; pxr::GfVec3d m_sRotateYXZ ; pxr::GfVec3d m_sRotateYZX ; pxr::GfVec3d m_sRotateZXY ; pxr::GfVec3d m_sRotateZYX ; double m_dRotateX ; double m_dRotateY ; double m_dRotateZ ; pxr::GfVec4d m_sOrient ; pxr::GfMatrix4d m_sTransform ; pxr::VtArray&lt;pxr::TfToken&gt; m_sXformOpOrder ; public: SMU_EXPORT SmUsdXformAttribute(ULONG lAttributeId, // in : pass-thru argument to SmAttribute constructor SmAttributeBehaviorType eBehavior, // in : pass-thru argument to SmAttribute constructor const pxr::GfVec3d * pTranslate = NULL, const pxr::GfVec3d * pScale = NULL, const pxr::GfVec3d * pRotateXYZ = NULL, const pxr::GfVec3d * pRotateXZY = NULL, const pxr::GfVec3d * pRotateYXZ = NULL, const pxr::GfVec3d * pRotateYZX = NULL, const pxr::GfVec3d * pRotateZXY = NULL, const pxr::GfVec3d * pRotateZYX = NULL, const double dRotateX = 0.0, const double dRotateY = 0.0, const double dRotateZ = 0.0, const pxr::GfVec4d * pOrient = NULL, const pxr::GfMatrix4d * pTransform = NULL, const pxr::VtArray&lt;pxr::TfToken&gt; * pXformOpOrder = NULL) : SmAttribute (lAttributeId, eBehavior), m_sTranslate (pTranslate ? *pTranslate : pxr::GfVec3d(0.0)), m_sScale (pScale ? *pScale : pxr::GfVec3d(1.0)), m_sRotateXYZ (pRotateXYZ ? *pRotateXYZ : pxr::GfVec3d(0.0)), m_sRotateXZY (pRotateXZY ? *pRotateXZY : pxr::GfVec3d(0.0)), m_sRotateYXZ (pRotateYXZ ? *pRotateYXZ : pxr::GfVec3d(0.0)), m_sRotateYZX (pRotateYZX ? *pRotateYZX : pxr::GfVec3d(0.0)), m_sRotateZXY (pRotateZXY ? *pRotateZXY : pxr::GfVec3d(0.0)), m_sRotateZYX (pRotateZYX ? *pRotateZYX : pxr::GfVec3d(0.0)), m_dRotateX (dRotateX), m_dRotateY (dRotateY), m_dRotateZ (dRotateZ), m_sOrient (pOrient ? *pOrient : pxr::GfVec4d(0.0, 0.0, 0.0, 1.0)), m_sTransform (pTransform ? *pTransform : pxr::GfMatrix4d(1.0)), m_sXformOpOrder(pXformOpOrder ? *pXformOpOrder : pxr::VtArray&lt;pxr::TfToken&gt;()) { } // end SmUsdXformAttribute::SmUsdXformAttribute SMU_EXPORT SmUsdXformAttribute(const SmUsdXformAttribute &amp; crOriginal); // virtual destructor - required implementation for derived objects SMU_EXPORT virtual ~SmUsdXformAttribute() { } // virtual Copy function - required implementation for derived objects SMU_EXPORT virtual SmAttribute * MakeCopy(const SmContext &amp; crContext) const { return (new (crContext) SmUsdXformAttribute( m_lAttributeID, m_eBehavior, &amp;m_sTranslate, &amp;m_sScale, &amp;m_sRotateXYZ, &amp;m_sRotateXZY, &amp;m_sRotateYXZ, &amp;m_sRotateYZX, &amp;m_sRotateZXY, &amp;m_sRotateZYX, m_dRotateX, m_dRotateY, m_dRotateZ, &amp;m_sOrient, &amp;m_sTransform, &amp;m_sXformOpOrder) ) ; } // Attach Xform attribute data to a UsdBrepArraySpecHandle - used when moving data from SMLib -&gt; USD SMU_EXPORT bool AttachAttributeToBrepInstance(const pxr::SdfPrimSpecHandle &amp; crUsdBrepArraySpecHandle, pxr::TfToken &amp; rtInstanceName); // Attach Xform attribute data to a UsdGeomXformable primSpec - used when moving data from SMLib -&gt; USD SMU_EXPORT bool AttachAttributeToXformable(const pxr::SdfPrimSpecHandle &amp; crPrimSpecHandle); // simple data access SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpTranslate() const {return m_sTranslate ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpScale () const {return m_sScale ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpRotateXYZ() const {return m_sRotateXYZ ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpRotateXZY() const {return m_sRotateXZY ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpRotateYXZ() const {return m_sRotateYXZ ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpRotateYZX() const {return m_sRotateYZX ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpRotateZXY() const {return m_sRotateZXY ; } SMU_EXPORT const pxr::GfVec3d &amp; GetXformOpRotateZYX() const {return m_sRotateZYX ; } SMU_EXPORT const double &amp; GetXformOpRotateX () const {return m_dRotateX ; } SMU_EXPORT const double &amp; GetXformOpRotateY () const {return m_dRotateY ; } SMU_EXPORT const double &amp; GetXformOpRotateZ () const {return m_dRotateZ ; } SMU_EXPORT const pxr::GfVec4d &amp; GetXformOpOrient () const {return m_sOrient ; } SMU_EXPORT const pxr::GfMatrix4d &amp; GetXformOpTransform() const {return m_sTransform ; } SMU_EXPORT const pxr::VtArray&lt;pxr::TfToken&gt; &amp; GetXformOpOrder() const {return m_sXformOpOrder ; } SMU_EXPORT void SetXformOpTranslate (const pxr::GfVec3d &amp; rTranslate) { m_sTranslate = rTranslate ; } SMU_EXPORT void SetXformOpScale (const pxr::GfVec3d &amp; rScale) { m_sScale = rScale ; } SMU_EXPORT void SetXformOpRotateXYZ (const pxr::GfVec3d &amp; rRotateXYZ) { m_sRotateXYZ = rRotateXYZ ; } SMU_EXPORT void SetXformOpRotateXZY (const pxr::GfVec3d &amp; rRotateXZY) { m_sRotateXZY = rRotateXZY ; } SMU_EXPORT void SetXformOpRotateYXZ (const pxr::GfVec3d &amp; rRotateYXZ) { m_sRotateYXZ = rRotateYXZ ; } SMU_EXPORT void SetXformOpRotateYZX (const pxr::GfVec3d &amp; rRotateYZX) { m_sRotateYZX = rRotateYZX ; } SMU_EXPORT void SetXformOpRotateZXY (const pxr::GfVec3d &amp; rRotateZXY) { m_sRotateZXY = rRotateZXY ; } SMU_EXPORT void SetXformOpRotateZYX (const pxr::GfVec3d &amp; rRotateZYX) { m_sRotateZYX = rRotateZYX ; } SMU_EXPORT void SetXformOpRotateX (double dRotateX) { m_dRotateX = dRotateX ; } SMU_EXPORT void SetXformOpRotateY (double dRotateY) { m_dRotateY = dRotateY ; } SMU_EXPORT void SetXformOpRotateZ (double dRotateZ) { m_dRotateZ = dRotateZ ; } SMU_EXPORT void SetXformOpOrient (const pxr::GfVec4d &amp; rOrient) { m_sOrient = rOrient ; } SMU_EXPORT void SetXformOpTransform (const pxr::GfMatrix4d &amp; rTransform) { m_sTransform = rTransform ; } SMU_EXPORT void SetXformOpOrder (const pxr::VtArray&lt;pxr::TfToken&gt; &amp; rXformOpOrder) { m_sXformOpOrder = rXformOpOrder ; } // Define GetType(), IsKindOf(), and virtual Dump() (Dump needs local implementation) SM_COMMON_FOR_EXPORT(SmUsdXformAttribute, SmAttribute, SmUsdXformAttribute_TYPE, SMU_EXPORT); }; //end class SmUsdXformAttribute #endif // no _SMU_ATTRIBUTE_H_", "keywords": []}, {"id": 3337, "doc_id": 3337, "filename": "api/program_listing_file_BREP_SM_USD_inc_SmuConfig.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_SmuConfig.h", "display_name": "SmuConfig.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_SmuConfig.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/SmuConfig.h File members: BREP_SM_USD/inc/SmuConfig.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /************************************************************************************ * FILE NAME --- SmuConfig.h * PURPOSE: Header file for local config used by BREP_SM_USD * **********************************************************************************/ #ifndef _SMU_CONFIG_H_ #define _SMU_CONFIG_H_ #ifdef _WIN32 #ifdef SMU_ENABLE_EXPORTS #define SMU_EXPORT __declspec( dllexport ) #define SMU_THREAD_LOCAL __declspec(thread) #else // no SMU_ENABLE_EXPORTS #define SMU_EXPORT __declspec( dllimport ) #define SMU_THREAD_LOCAL __declspec(thread) #endif // no SMU_ENABLE_EXPORTS #else // no _WIN32 #define SMU_EXPORT #define SMU_THREAD_LOCAL thread_local #endif // no _WIN32 // debug blocks #ifdef _DEBUG # ifndef SMU_DEBUG_CODE # define SMU_DEBUG_CODE 1 # endif #endif // _DEBUG #endif // no _SMU_CONFIG_H_", "keywords": []}, {"id": 3338, "doc_id": 3338, "filename": "api/program_listing_file_BREP_SM_USD_inc_SmuConvert.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_SmuConvert.h", "display_name": "SmuConvert.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_SmuConvert.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/SmuConvert.h File members: BREP_SM_USD/inc/SmuConvert.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /******************************************************************/ #ifndef _SMU_CONVERT_H_ #define _SMU_CONVERT_H_ #include &quot;SmuConfig.h&quot; // defines (or omits for debug) #include &quot;SmMessages.h&quot; #include &quot;SmTypes.h&quot; #include &lt;cstdint&gt; #include &lt;vector&gt; // pixar includes #include &quot;UsdBrepSuppressPixarWarningsPush.h&quot; // turn off compile warnings for problematic pixar include files #include &lt;pxr/pxr.h&gt; #include &lt;pxr/usd/usd/prim.h&gt; #include &lt;pxr/usd/sdf/path.h&gt; #include &lt;pxr/usd/usdGeom/gprim.h&gt; #include &lt;pxr/usd/usdGeom/capsule.h&gt; #include &quot;UsdBrepSuppressPixarWarningsPop.h&quot; // done loading problematic pixar headers - restore compile warnings #include &lt;pxr/usd/usdGeom/cone.h&gt; #include &lt;pxr/usd/usdGeom/cube.h&gt; #include &lt;pxr/usd/usdGeom/cylinder.h&gt; #include &lt;pxr/usd/usdGeom/sphere.h&gt; #include &lt;pxr/usd/usdGeom/mesh.h&gt; namespace UsdBrepData{ class UsdBrepArrayData; class UsdBrepArraySpans; } class SmBrep; class SmBrepData; class SmPolyBrep; class SmAttribute; template&lt;class TYPE&gt; class SmTArray ; // character buffer size #define SMU_TBLOCK_SIZE 1024 // load buffer:[size=SMU_TBLOCK_SIZE] with formatted string: - always use 1 or more specifiers and // string precision specifiers #ifdef _UNICODE template &lt;typename... Args&gt; void inline smu_sprintf(wchar_t* buff, wchar_t* format, Args... args) { _sntprintf(buff, (size_t)(SMU_TBLOCK_SIZE - 1), format, args...); buff[SMU_TBLOCK_SIZE - 1] = L&#x27;\\0&#x27;; } #else template &lt;typename... Args&gt; void inline smu_sprintf(char* buff, const char* format, Args... args) { snprintf(buff, (size_t)(SMU_TBLOCK_SIZE), format, args...); } #endif // send char buffers to targets: on windows in debug - tgt OutputDebugString() // on Linux/macOS in debug - tgt stderr // if(b_OutputLong) - tgt LongFile (if pBuff use pBuff else pBuffForFile) // if(b_OutputThin) - tgt ThinFile (if pBuffForFile use pBuffForFile else pBuff) // pBuff: in: string for output window and longFile when b_OutputLong=true // pBuffForFile: in: string for thinFile when b_OutputThin=true void smu_WriteBuffer(const TCHAR* pBuff, const TCHAR* pBuffForFile = NULL); namespace SMU_BrepConvert { struct BrepImportResult { SmBrep* pBrep = nullptr; std::uint32_t iPackedBrepIndex = 0; SmStatus status = SM_ERR; bool bRemainingMembersSkipped = false; }; // SMLib to USD // Append vector of SmBreps to UsdBrepArray SMU_EXPORT SmStatus BrepAppend_SMLibToUsd (std::vector&lt;SmBrep*&gt;&amp; rSmBreps, // i/o: in : &#x27;from&#x27; SmBreps to convert to a UsdBrepArrayData // out: an SmSdfPathAttribute(UsdBrepArraypath) is added to each SmBrep_ii. pxr::UsdPrim&amp; crUsdBrepArray, // in : Tgt UsdBrepArray being appended bool bExportUVCurves = true, // in : when true, export Edgeuse UV trim curves (UVCurves) to USD bool bBoundUnboundedFaceRanges = false ); // in : when true, replace unbounded face ranges with trim-curve bounds in USD only // 0x0 to ignore. // Move one SMU_EXPORT SmStatus AppendSmBrepData_ToUsdBrepArrayData (SmBrepData * pSmBrepData, // i/o: in : &#x27;from&#x27; SmBrepData to convert to a UsdBrepArrayData // out: a SmSdfPathAttribute( UsdBrepArrayPath ) may be added to each SmBrep_ii. SmTArray&lt;SmAttribute*&gt; &amp; rAttributes, // in : attributes for items in pSmBrepData (from SmBrepData::FromBrep() ) UsdBrepData::UsdBrepArrayData &amp; rArrays, // i/o: in : UsdBrepArrayData with preexisting Brep data // out: Augmented with pSmBrepData content SmBrep * pOptSmBrep, // in : optional associated SmBrep - required for attribute propagation - NULL to ignore pxr::SdfPathVector * pOptPaths); // in : optional SdfPathVector of UsdBrepArrayPaths to be added to each SmBrep_ii as an SMLib attribute // Append vector of SmBreps to UsdBrepArrayData SMU_EXPORT SmStatus BrepAppend_SMLibToUsdBrep (std::vector&lt;SmBrep*&gt; &amp; rSmBreps, // i/o: target SmBreps to add to rArrays, (a SmSdfPathAttribute(UsdBrepArraypath) is added to each SmBrep_ii) UsdBrepData::UsdBrepArrayData &amp; rArrays, // i/o: UsdBrepArrayData augmented with rSmBreps data pxr::SdfPathVector * pOptPaths=nullptr, // in : optional SdfPathVector of UsdBrepArrayPaths to be added to each SmBrep_ii as an SMLib attribute // 0x0 to ignore. default:[0x0] bool bExportUVCurves = true, // in : when true, export Edgeuse UV trim curves (UVCurves) into rArrays for later USD writing bool bBoundUnboundedFaceRanges = false ) ; // in : when true, replace unbounded face ranges with trim-curve bounds in USD only // USD to SMLib // Move all UsdGeomGprim Brep members to an array of SmBreps. Conversion // is all-or-nothing: existing caller-owned entries are preserved and new // Breps are appended only after every packed member converts successfully. SMU_EXPORT SmStatus BrepMove_UsdToSMLib (const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const pxr::UsdGeomGprim &amp; crUsdBrepArray, // in : Usd prim being converted to an SmBrep std::vector&lt;SmBrep*&gt; &amp; rSmBreps, // i/o: Existing entries preserved; new Breps appended on success SmBoolean bHealerIsEnabled = TRUE // in : default TRUE: healer is enabled FALSE: disable healer ); // Attempt every locatable member of one UsdGeomGprim BrepArray. Results // are appended in packed-member order. A nonNULL pBrep is owned by the // caller; failed members have pBrep == NULL and their conversion status. // A malformed container that prevents member enumeration returns an error // without appending results. A malformed member boundary appends one // failure with bRemainingMembersSkipped == true and stops that BrepArray. // Set bStopAfterFailure for the legacy strict caller&#x27;s fail-fast behavior. // Process-level failures always return immediately without appending. SMU_EXPORT SmStatus BrepMove_UsdToSMLibWithResults (const SmContext &amp; crSmContext, const pxr::UsdGeomGprim &amp; crUsdBrepArray, std::vector&lt;BrepImportResult&gt; &amp; rResults, SmBoolean bHealerIsEnabled = TRUE, SmBoolean bStopAfterFailure = FALSE ); // move one UsdGeomGprim Brep member to SmBrep SMU_EXPORT SmStatus BrepMove_OneUsdBrepToSMLib ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const UsdBrepData::UsdBrepArrayData &amp; rArrays, // in : all brep attribute values from UsdBrepData::BrepReadFromUsdStage() UsdBrepData::UsdBrepArraySpans &amp; rSpans, // i/o: Container for Brep_ii object count and 1stIndex values computed from the rArrays member arrays. uint32_t iBrepIndex, // in : UsdBrepArrayData tgt item index to convert to SmBrep SmBrep *&amp; prSmBrep_ii, // out: Newly created SmBrep, or NULL on failure SmBoolean bHealerIsEnabled = TRUE // in : default TRUE: healer is enabled FALSE: disable healer ); // move one AppendedBrepArrayData member to SmBrepData SMU_EXPORT SmStatus BrepMove_OneUsdBrepToSMLibData ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const UsdBrepData::UsdBrepArrayData &amp; rArrays, // in : all brep attribute values from UsdBrepData::BrepReadFromUsdStage() UsdBrepData::UsdBrepArraySpans &amp; rSpans, // i/o: Container for Brep_ii object count and 1stIndex values computed from the rArrays member arrays. uint32_t iBrepIndex, // in : UsdBrepArrayData tgt item index to convert to SmBrep SmBrepData *&amp; prSmBrepData_ii, // i/o: Must be NULL; receives a new SmBrepData on success SmTArray&lt;SmAttribute*&gt; &amp; rAttributes // out: Referenced attributes; empty on failure ); // Create SmBrep from UsdGeomCapsule SMU_EXPORT SmStatus CreateSmBrep_FromUsdCapsule ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const pxr::UsdGeomCapsule &amp; crUsdCapsule, // in : Usd prim being converted to an SmBrep SmBrep *&amp; prSmBrep // out: The newly created SmBrep ); // Create SmBrep from UsdGeomCone SMU_EXPORT SmStatus CreateSmBrep_FromUsdCone ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const pxr::UsdGeomCone &amp; crUsdCone, // in : Usd prim being converted to an SmBrep SmBrep *&amp; prSmBrep // out: The newly created SmBrep ); // Create SmBrep from UsdGeomCube SMU_EXPORT SmStatus CreateSmBrep_FromUsdCube ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const pxr::UsdGeomCube &amp; crUsdCube, // in : Usd prim being converted to an SmBrep SmBrep *&amp; prSmBrep // out: The newly created SmBrep ); // Create SmBrep from UsdGeomCylinder SMU_EXPORT SmStatus CreateSmBrep_FromUsdCylinder ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const pxr::UsdGeomCylinder &amp; crUsdCylinder, // in : Usd prim being converted to an SmBrep SmBrep *&amp; prSmBrep // out: The newly created SmBrep ); // Create SmBrep from UsdGeomSphere SMU_EXPORT SmStatus CreateSmBrep_FromUsdSphere ( const SmContext &amp; crSmContext, // in : Context in which prSmBrep is created const pxr::UsdGeomSphere &amp; crUsdSphere, // in : Usd prim being converted to an SmBrep SmBrep *&amp; prSmBrep // out: The newly created SmBrep ); // Create SmPolyBrep from UsdGeomMesh SMU_EXPORT SmStatus CreateSmPolyBrep_FromUsdMesh ( const SmContext &amp; crSmContext, // in : Context in which prSmPolyBrep is created const pxr::UsdGeomMesh &amp; crUsdGeomMesh, // in : Usd prim being converted to an SmPolyBrep SmPolyBrep *&amp; prSmPolyBrep // out: The newly created SmPolyBrep ); } // end namespace SMU_BrepConvert #endif // no _SMU_CONVERT_H_", "keywords": []}, {"id": 3339, "doc_id": 3339, "filename": "api/program_listing_file_BREP_SM_USD_inc_SmuTessellate.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_SmuTessellate.h", "display_name": "SmuTessellate.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_SmuTessellate.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/SmuTessellate.h File members: BREP_SM_USD/inc/SmuTessellate.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /******************************************************************/ #ifndef _SMU_TESSELLATE_H_ #define _SMU_TESSELLATE_H_ #include &quot;SmuConfig.h&quot; // define: SMU_EXPORT // pixar includes #include &lt;pxr/usd/usdGeom/xformOp.h&gt; // SMLib includes #include &quot;SmTypes.h&quot; #include &lt;memory&gt; class SmBrep; class SmPolyBrep; class SmFace; class SmSdfPathAttribute; template&lt;class TYPE&gt; class SmTArray ; namespace SMU_BrepConvert { // Replace USD boundary arrays; finite, positive angle in degrees. Omit edges with fewer than two points. // On sampling failure, retain valid boundaries. SMU_EXPORT SmStatus GetBoundaryData ( SmBrep* pBrep, double dAngleTolDeg, pxr::VtArray&lt;pxr::GfVec3f&gt;&amp; rPoints, pxr::VtIntArray&amp; rVertexCounts ); // Get Mesh data from an SmPolyBrep, prepared for authoring UsdGeomMesh SMU_EXPORT SmStatus GetMeshData ( SmPolyBrep &amp; crSmPolyBrep, // in : Get mesh data from this SmPolyBrep pxr::VtArray&lt;pxr::GfVec3f&gt; &amp; rExtent, // out: Mesh Extent pxr::VtArray&lt;pxr::GfVec3f&gt; &amp; rPoints, // out: Mesh vertex locations pxr::VtIntArray &amp; rFaceVertexCounts, // out: Number of vertices in each face of the mesh pxr::VtIntArray &amp; rFaceVertexIndices, // out: Flat list of the index of each vertex of each face in the mesh pxr::VtArray&lt;pxr::GfVec3f&gt; &amp; rPrimvarNormals, // out: Mesh vertex normals pxr::VtIntArray &amp; rPrimvarNormalsIndices, // out: Flat list of the index of each normal of each vertex in the mesh pxr::TfToken &amp; sPrimvarNormalsInterpolation, // out: face varying normals interpolation pxr::TfToken &amp; rSubdivisionScheme, // out: None pxr::VtArray&lt;pxr::VtIntArray&gt; * pOptGeomSubsetIndices = NULL, SmTArray&lt;SmSdfPathAttribute*&gt; * pOptSubsetMaterialPaths = NULL ); // Own a standalone tessellated mesh, i.e. ConvertToPolyBrep output. // // Deletion, not extraction: ~SmPolyBrep clears source vertex back-pointers while the // mesh&#x27;s flag is on, but a standalone mesh&#x27;s polyvertices point into the internal // tessellation copy, which ConvertToPolyBrep already destroyed before returning. // Keeping the caller&#x27;s source Brep alive does not make that read safe. The deleter // therefore disables the flag first, so deletion is safe in either source/mesh order // and whatever the flag was left set to. // // Do not put a borrowed SmTess cache mesh in here: those are owned elsewhere and keep // their back-pointers on purpose. struct TessellatedMeshDeleter { SMU_EXPORT void operator()(SmPolyBrep* pMesh) const; }; using TessellatedMeshPtr = std::unique_ptr&lt;SmPolyBrep, TessellatedMeshDeleter&gt;; // Extract USD mesh arrays; deep-copies material paths and restores the mesh&#x27;s // back-pointer flag on exit. // The source Brep must stay alive AND topologically unmodified until extraction // returns: the mesh labels faces with SmFace pointers into the source, and nothing // tracks faces replaced or deleted after tessellation, so a mutator run in between // leaves labels that are read here for normals and material lookup. // That is the extraction contract and is separate from deletion, which // TessellatedMeshPtr handles. // rMaterialPaths pairs with rSubsetIndices; an unbound subset gives an empty path. // An empty mesh yields empty arrays and an empty extent, and still returns SM_SUCCESS. // Not thread-safe on a single mesh. SMU_EXPORT SmStatus GetTessellatedMeshData ( SmPolyBrep&amp; rMesh, pxr::VtArray&lt;pxr::GfVec3f&gt;&amp; rExtent, pxr::VtArray&lt;pxr::GfVec3f&gt;&amp; rPoints, pxr::VtIntArray&amp; rFaceVertexCounts, pxr::VtIntArray&amp; rFaceVertexIndices, pxr::VtArray&lt;pxr::GfVec3f&gt;&amp; rNormals, pxr::VtIntArray&amp; rNormalsIndices, pxr::TfToken&amp; rNormalsInterpolation, pxr::TfToken&amp; rSubdivisionScheme, pxr::VtArray&lt;pxr::VtIntArray&gt;&amp; rSubsetIndices, pxr::VtArray&lt;pxr::SdfPath&gt;&amp; rMaterialPaths ); // Author precomputed mesh arrays (as from GetTessellatedMeshData) onto a UsdGeomMesh SMU_EXPORT SmStatus PopulateMeshAttr ( const pxr::VtArray&lt;pxr::GfVec3f&gt; &amp; crExtent, const pxr::VtArray&lt;pxr::GfVec3f&gt; &amp; crPoints, const pxr::VtIntArray &amp; crFaceVertexCounts, const pxr::VtIntArray &amp; crFaceVertexIndices, const pxr::VtArray&lt;pxr::GfVec3f&gt; &amp; crNormals, const pxr::VtIntArray &amp; crNormalsIndices, const pxr::TfToken &amp; crNormalsInterpolation, const pxr::TfToken &amp; crSubdivisionScheme, const pxr::VtArray&lt;pxr::VtIntArray&gt; &amp; crSubsetIndices, const pxr::VtArray&lt;pxr::SdfPath&gt; &amp; crMaterialPaths, // pairs with crSubsetIndices; empty = unbound const pxr::SdfPrimSpecHandle &amp; rPrimSpecHandle ); // Convert an SmPolyBrep to a UsdGeomMesh SMU_EXPORT SmStatus PopulateMeshAttr ( SmPolyBrep &amp; crSmPolyBrep, // in : PolyBrep being converted to a UsdGeomMesh const pxr::SdfPrimSpecHandle &amp; rPrimSpecHandle // in : PrimSpecHandle of the UsdGeomMesh ); } // end namespace SMU_BrepConvert #endif // no _SMU_TESSELLATE_H_", "keywords": []}, {"id": 3340, "doc_id": 3340, "filename": "api/program_listing_file_BREP_SM_USD_inc_SmuTokens.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_SmuTokens.h", "display_name": "SmuTokens.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_SmuTokens.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/SmuTokens.h File members: BREP_SM_USD/inc/SmuTokens.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /******************************************************************/ #ifndef _SMU_TOKENS_H_ #define _SMU_TOKENS_H_ #include &quot;UsdBrepSuppressPixarWarningsPush.h&quot; // turn off known compile warnings for code owned by pixar # include &lt;pxr/base/tf/staticTokens.h&gt; #include &quot;UsdBrepSuppressPixarWarningsPop.h&quot; // done loading pixar code - restore suspended compile warnings #include &quot;SmuConfig.h&quot; PXR_NAMESPACE_OPEN_SCOPE #ifndef SMU_TESS_TOKENS #define SMU_TESS_TOKENS \\ ((primvarNormals, &quot;primvars:normals&quot; )) \\ ((primvarNormalsIndices, &quot;primvars:normals:indices&quot; )) #endif // no SMU_TESS_TOKENS // TF_DECLARE_PUBLIC_TOKENS three argument version exports declaresd tokens from a DLL on windows // needed if any project other than BREP_SM_USD will be using these tokens TF_DECLARE_PUBLIC_TOKENS(SmuTessTokens, SMU_EXPORT, SMU_TESS_TOKENS); PXR_NAMESPACE_CLOSE_SCOPE #endif // no _SMU_TOKENS_H_", "keywords": []}, {"id": 3341, "doc_id": 3341, "filename": "api/program_listing_file_BREP_SM_USD_inc_SmuUtilities.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_SmuUtilities.h", "display_name": "SmuUtilities.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_SmuUtilities.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/SmuUtilities.h File members: BREP_SM_USD/inc/SmuUtilities.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /******************************************************************/ #ifndef _SMU_UTILITIES_H_ #define _SMU_UTILITIES_H_ #include &quot;SmuConfig.h&quot; // pixar includes #include &lt;pxr/usd/usdGeom/xformOp.h&gt; // SMLib includes #include &quot;SmTypes.h&quot; class SmBrep; class SmCurve; class SmBSplineSurface; class SmVector3d; class SmAxis2Placement; namespace SMU_BrepConvert { // // Convenience functions to apply a UsdXformOp to an SMLib object // // apply a UsdGeomXformOp to an SmCurve SMU_EXPORT SmStatus ApplyUsdXformOp ( SmCurve &amp; rCurve, // in : Curve to which the transform is applied const pxr::UsdGeomXformOp &amp; crXformOp // in : Xform to apply to rCurve ); // Note: At some point we&#x27;ll need to apply transforms to Analytics and offsets. When scale is not uniform, surfaces must be converted to BSSurfaces. // apply a UsdGeomXformOp to an SmBSplineSurface SMU_EXPORT SmStatus ApplyUsdXformOp ( SmBSplineSurface &amp; rBSSurface, // in : Surface to which the transform is applied const pxr::UsdGeomXformOp &amp; crXformOp // in : Xform to apply to rBSSurface ); // apply a UsdGeomXformOp to an SmBrep SMU_EXPORT SmStatus ApplyUsdXformOp ( SmBrep &amp; rBrep, // in : Brep to which the transform is applied const pxr::UsdGeomXformOp &amp; crXformOp // in : Xform to apply to rBrep ); // // Translate transformations between SMLib and Usd formats // // Convert a UsdXform to SMLib compatible scale and transform SMU_EXPORT SmStatus UsdXformToSmTransform ( const pxr::UsdGeomXformOp &amp; crXformOp, // in : Xform that will be converted to SMLib standard SmVector3d &amp; rScale, // out: Scaling output SmAxis2Placement &amp; rTransform // out: Rotation and translation ); // Convert an SMLib scale and tranform to an Usd 4x4 matrix SMU_EXPORT SmStatus SmTransformToUsdXform ( const SmVector3d &amp; rScale, // in : Scaling const SmAxis2Placement &amp; rTransform, // in : Rotation and translation pxr::GfMatrix4d &amp; r4x4 // out: Transformation as 4x4 matrix ); // Convert an SMLib scale and tranform to an UsdGeomXformOp SMU_EXPORT SmStatus SmTransformToUsdXform ( const SmVector3d &amp; rScale, // in : Scaling const SmAxis2Placement &amp; rTransform, // in : Rotation and translation pxr::UsdGeomXformOp &amp; rXformOp // out: Transformation as UsdGeomXformOp ); // // Functions to access the SDF API, for stage authoring within an SdfChangeBlock // SMU_EXPORT pxr::SdfPrimSpecHandle smuGenerateBrepMetadata(const pxr::SdfPrimSpecHandle &amp; rParentSpecHandle, const std::string sName, std::string * pOptDisplayName, pxr::GfMatrix4d &amp; rBrepMat, ULONG uIndex, const pxr::SdfPath materialPath); SMU_EXPORT pxr::SdfPrimSpecHandle smuGenerateMeshMetadata(const pxr::SdfPrimSpecHandle &amp; rParentSpecHandle, const std::string sName, std::string * pOptDisplayName, pxr::GfMatrix4d &amp; rBrepMat, bool bDoubleSided, ULONG uIndex, const pxr::SdfPath materialPath); } // end namespace SMU_BrepConvert #endif // no _SMU_UTILITIES_H_", "keywords": []}, {"id": 3342, "doc_id": 3342, "filename": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepDebugTools.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepDebugTools.h", "display_name": "UsdBrepDebugTools.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepDebugTools.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/UsdBrepDebugTools.h File members: BREP_SM_USD/inc/UsdBrepDebugTools.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /********************************************************************************************************************* * FILE NAME --- UsdBrepDebugTools.h * PURPOSE: Debugging tools for UsdBrepArrayData and UsdBrepArraySpans classes * ******************************************************************************************************************/ #ifndef _USD_BREP_DEBUG_TOOLS_H_ #define _USD_BREP_DEBUG_TOOLS_H_ #include &quot;SmuConfig.h&quot; // USD includes #include &quot;UsdBrepHeaders.h&quot; namespace UsdBrepData { class UsdBrepArrayData; class UsdBrepArraySpans; // prettyPrint UsdBrepArrayData and UsdBrepArraySpans SMU_EXPORT void Dump_BrepArrayData(const UsdBrepArrayData&amp; rArrays, bool bDumpData = false); SMU_EXPORT void Dump_BrepArraySpans(const UsdBrepArrayData&amp; rArrays, const UsdBrepArraySpans&amp; rSpans, bool bDumpData = false); SMU_EXPORT void Dump_PrimProperties(const pxr::UsdPrim&amp; crPrim); SMU_EXPORT void Dump_PrimSpecProperties(const pxr::SdfPrimSpecHandle&amp; rPrimSpecHandle); SMU_EXPORT void Dump_PrimProperties_fromPrimSpecHandle(const pxr::SdfPrimSpecHandle&amp; crPrimSpecHandle, pxr::UsdStageRefPtr&amp; rStage); } // end namespace UsdBrepData /********************************************************************************************************************* outputFiles directory ********************************************************************************************************************/ SMU_EXPORT bool usdBrep_CreateOutputFiles(); /********************************************************************************************************************* standardized I/O ********************************************************************************************************************/ SMU_EXPORT void usdBrep_WriteString(const std::string&amp; string); #endif // no _USD_BREP_DEBUG_TOOLS_H_", "keywords": []}, {"id": 3343, "doc_id": 3343, "filename": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepSuppressPixarWarningsPop.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepSuppressPixarWarningsPop.h", "display_name": "UsdBrepSuppressPixarWarningsPop.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepSuppressPixarWarningsPop.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/UsdBrepSuppressPixarWarningsPop.h File members: BREP_SM_USD/inc/UsdBrepSuppressPixarWarningsPop.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /************************************************************************************ * FILE NAME --- UsdBrepSuppressPixarWarningsPop.h * PURPOSE: Standardize suppressing pixar compile warnings * PURPOSE: Include after pixar header file includes to restore compile warnings * ***********************************************************************************/ // don&#x27;t add compile guards here - needs to load once in every header file that calls it. // done including pixar code - restore turned off compile warnings #ifdef _MSC_VER # pragma warning(pop) #elif defined(__GNUC__) # ifdef OMNI_USD_SUPPRESS_DEPRECATION_WARNINGS # define __DEPRECATED __attribute__((deprecated)) # undef OMNI_USD_SUPPRESS_DEPRECATION_WARNINGS # endif // OMNI_USD_SUPPRESS_DEPRECATION_WARNINGS #endif // _MSC_VER or __GNUC__ // don&#x27;t add compile guards here - needs to load once in every header file that calls it.", "keywords": []}, {"id": 3344, "doc_id": 3344, "filename": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepSuppressPixarWarningsPush.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepSuppressPixarWarningsPush.h", "display_name": "UsdBrepSuppressPixarWarningsPush.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_SM_USD_inc_UsdBrepSuppressPixarWarningsPush.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_SM_USD/inc/UsdBrepSuppressPixarWarningsPush.h File members: BREP_SM_USD/inc/UsdBrepSuppressPixarWarningsPush.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 /************************************************************************************ * FILE NAME --- UsdBrepSuppressPixarWarningsPush.h * PURPOSE: Standardize suppressing pixar compile warnings * NOTES: Include before pixar header file includes to suppress pixar compile warnings * ***********************************************************************************/ // don&#x27;t add compile guards here - needs to load once in every header file that calls it. // pragma warning labeled with a ** are needed in windows to suppress pxr file compile warnings. // ^^ are not needed in windows. // turn off known compiler warnings for code owned by pixar #ifdef _MSC_VER # pragma warning(push) # pragma warning(disable : 4100) // Unreferenced formal parameter # pragma warning(disable : 4127) // Conditional expression is constant # pragma warning(disable : 4201) // Nonstandard extension used: nameless struct/union # pragma warning(disable : 4245) // &#x27;initializing&#x27;: conversion from &#x27;int&#x27; to &#x27;const size_t&#x27;, signed/unsigned mismatch # pragma warning(disable : 4251) // class needs to have dll-interface to be used by clients of class # pragma warning(disable : 4273) // inconsistent dll linkage # ifndef NOMINMAX # define NOMINMAX // Make sure nobody #defines min or max # endif # undef small // defined in rpcndr.h #elif defined(__GNUC__) // This suppresses deprecated header warnings, which is impossible with pragmas. // Alternative is to specify -Wno-deprecated build option, but that disables other useful warnings too. # ifdef __DEPRECATED # define OMNI_USD_SUPPRESS_DEPRECATION_WARNINGS # undef __DEPRECATED # endif // __DEPRECATED #endif // _MSC_VER or __GNUC__", "keywords": []}, {"id": 3345, "doc_id": 3345, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepCoedgeBuilder.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepCoedgeBuilder.h", "display_name": "BrepCoedgeBuilder.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepCoedgeBuilder.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepCoedgeBuilder.h File members: BREP_STAGING/inc/BrepCoedgeBuilder.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_COEDGE_BUILDER_H #define BREP_COEDGE_BUILDER_H #include &quot;BrepSourceData.h&quot; #include &quot;BrepStagingState.h&quot; struct StagedCoedgeBuildResult { uint32_t uiEdgeuseTargetIndex = kStagedNoObjectIndex; bool bFirstCoedge = false; bool bExplicitOuterLoop = false; bool bReverseStagedLoop = false; bool bStagedEdgeuseMatchesSourceOrient = false; bool bBottomSideEntry = false; }; class StagedBrepCoedgeBuilder { public: StagedBrepCoedgeBuilder( BrepStagingState&amp; rState, uint32_t uiCurrentLoopTraversalCount, uint32_t uiCurrentCoedgeTraversalCount, uint32_t uiOuterLoopSourceIndex, uint32_t uiOuterLoopEdgeuseStartIndex, uint32_t uiOuterLoopEdgeuseCount, bool bHasImpliedNaturalBoundary ); bool IsFirstLoop() const; bool IsFirstCoedge() const; bool IsCurrentLoopExplicitOuterLoop() const; bool IsCurrentLoopAugmentedOuterLoop() const; bool IsCurrentOuterLoop() const; uint32_t GetReserveCountForCurrentLoop(uint32_t uiLoopEdgeuseCount) const; bool ShouldReverseLoop(bool bSourceSameLoopOrient) const; bool ShouldEdgeuseMatchSourceOrientation(bool bReverseLoop, bool bSourceSameEdgeOrient) const; bool ShouldEdgeuseEnterBottomSide(bool bSameEdgeuseOrient) const; uint32_t GetEdgeuseTargetIndexForCurrentCoedge(bool bReverseLoop, uint32_t uiLoopEdgeuseCount) const; void ReserveEdgeuses(uint32_t uiAdditionalEdgeuseCount); void SetEdgeuseForCurrentTraversal(uint32_t uiEdgeuseIndex, bool bSameEdgeuseOrient, bool bBottomSideEntry); StagedCoedgeBuildResult AddSourceCoedgeForCurrentTraversal(const SourceLoopData&amp; rLoopData, const SourceCoedgeData&amp; rCoedgeData); private: bool ShouldReserveAugmentedOuterLoopForFirstInnerLoop(bool bFirstLoop, bool bIsOuterLoop) const; BrepStagingState&amp; m_rState; uint32_t m_uiCurrentLoopTraversalCount = 0; uint32_t m_uiCurrentCoedgeTraversalCount = 0; uint32_t m_uiOuterLoopSourceIndex = 0; uint32_t m_uiOuterLoopEdgeuseStartIndex = 0; uint32_t m_uiOuterLoopEdgeuseCount = 0; bool m_bHasImpliedNaturalBoundary = false; }; #endif // BREP_COEDGE_BUILDER_H", "keywords": []}, {"id": 3346, "doc_id": 3346, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepEdgeVertexBuilder.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepEdgeVertexBuilder.h", "display_name": "BrepEdgeVertexBuilder.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepEdgeVertexBuilder.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepEdgeVertexBuilder.h File members: BREP_STAGING/inc/BrepEdgeVertexBuilder.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_EDGE_VERTEX_BUILDER_H #define BREP_EDGE_VERTEX_BUILDER_H #include &quot;BrepSourceData.h&quot; #include &quot;BrepStatus.h&quot; #include &quot;UsdBrepHeaders.h&quot; // pxr warning-suppression guard; keep ahead of &lt;pxr/..&gt; includes #include &lt;pxr/base/gf/range1d.h&gt; #include &lt;pxr/base/gf/vec3d.h&gt; #include &lt;pxr/base/vt/array.h&gt; #include &lt;cstdint&gt; namespace UsdBrepData { class UsdBrepBuilder; } class NaturalBoundaryBuilder; class StagedBrepEdgeVertexBuilder { public: explicit StagedBrepEdgeVertexBuilder(BrepStagingState&amp; rState); BrepStatus AddSourceVertex(const SourceVertexData&amp; rVertexData, uint32_t&amp; rVertexIndex); BrepStatus AddSourceEdgeForCurrentTraversal( const SourceEdgeData&amp; rEdgeData, uint32_t uiStartVertexIndex, uint32_t uiEndVertexIndex, pxr::GfRange1d&amp; rEdgeInterval ); private: friend class NaturalBoundaryBuilder; uint32_t AddStagedLineCurve(const pxr::GfVec3d&amp; rOrigin, const pxr::GfVec3d&amp; rDirection); uint32_t AddStagedCircleCurve(const pxr::GfVec3d&amp; rCenter, const pxr::GfVec3d&amp; rAxis, const pxr::GfVec3d&amp; rRefDirection, double dRadius); uint32_t AddStagedBSplineCurve( uint32_t uiVertexCount, uint32_t uiOrder, const pxr::VtArray&lt;double&gt;&amp; rKnots, const pxr::VtArray&lt;pxr::GfVec3d&gt;&amp; rControlVertices, const pxr::VtArray&lt;double&gt;&amp; rWeights ); uint32_t AddStagedEdgeForCurrentTraversal( StagedCurveType eCurveType, const pxr::GfRange1d&amp; rInterval, uint32_t uiStartVertexIndex, uint32_t uiEndVertexIndex ); void AddStagedImpliedBoundaryEdgeuse(uint32_t uiEdgeIndex, StagedOrientType eOrientType, StagedRadialEntryType eEntrySideType); void AddStagedImpliedBoundaryEdgeuses(uint32_t uiFirstEdgeuseIndex); uint32_t SetStagedImpliedBoundaryEdgeuses(uint32_t uiFirstEdgeuseIndex); uint32_t AddStagedVertexPoint(const pxr::GfVec3d&amp; rPoint); uint32_t AddStagedEdgeCurve(const StagedCurveData&amp; rCurveData); uint32_t AddStagedEdge(const StagedEdgeData&amp; rEdgeData); bool TryGetStagedVertexPoint(uint32_t uiVertexIndex, pxr::GfVec3d&amp; rPoint) const; BrepStagingState&amp; m_rState; }; #endif // BREP_EDGE_VERTEX_BUILDER_H", "keywords": []}, {"id": 3347, "doc_id": 3347, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepExtentBuilder.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepExtentBuilder.h", "display_name": "BrepExtentBuilder.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepExtentBuilder.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepExtentBuilder.h File members: BREP_STAGING/inc/BrepExtentBuilder.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_EXTENT_BUILDER_H #define BREP_EXTENT_BUILDER_H #include &quot;BrepStagingState.h&quot; #include &quot;UsdBrepHeaders.h&quot; // pxr warning-suppression guard; keep ahead of &lt;pxr/..&gt; includes #include &lt;pxr/base/gf/vec3d.h&gt; class StagedBrepExtentBuilder { public: explicit StagedBrepExtentBuilder(BrepStagingState&amp; rState); void UpdateExtent(); private: void ExpandExtentWithStagedEdgeCurveSet(bool bWireEdgeSet, pxr::GfVec3d&amp; rExtentMin, pxr::GfVec3d&amp; rExtentMax, bool&amp; bHasGeometry); void ExpandExtentWithStagedFaceSurfaces(pxr::GfVec3d&amp; rExtentMin, pxr::GfVec3d&amp; rExtentMax, bool&amp; bHasGeometry); BrepStagingState&amp; m_rState; }; #endif // BREP_EXTENT_BUILDER_H", "keywords": []}, {"id": 3348, "doc_id": 3348, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepFaceTraversalPlanner.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepFaceTraversalPlanner.h", "display_name": "BrepFaceTraversalPlanner.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepFaceTraversalPlanner.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepFaceTraversalPlanner.h File members: BREP_STAGING/inc/BrepFaceTraversalPlanner.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_FACE_TRAVERSAL_PLANNER_H #define BREP_FACE_TRAVERSAL_PLANNER_H #include &quot;BrepSourceData.h&quot; #include &quot;BrepStatus.h&quot; #include &lt;cstdint&gt; #include &lt;vector&gt; // Resolve, from kernel-neutral inputs, which loop bounds a face (the &quot;outer&quot; loop) and whether the // face&#x27;s boundary is implied by the surface&#x27;s natural parameter range. This is a staging decision that // is identical across CAD kernels, so it lives in the shared layer and is fed neutral facts by each // IBrepSource adapter (instead of being re-implemented per kernel). // // Decision order (source index is authoritative when in range): // index &lt; loopCount : explicit outer; trust it; ignore orientation. // index == loopCount : source declares implied natural boundary; trust it. // index &gt; loopCount : unknown \u2014 orientation fallback only: // closed + all-CW \u2192 implied natural boundary; // else recover a CCW outer if present; // else flag out-of-range without inventing a boundary. // // uiSourceOuterLoopIndex : the loop the source declares as outer; == uiLoopCount means &quot;none / // implied natural boundary&quot;; &gt; uiLoopCount is unknown/malformed. // bClosedSurface : surface is closed in U and/or V (its natural range can imply a boundary). // bAllLoopsCW : every explicit loop runs clockwise on the surface (so none is the outer). // uiCCWLoopCount : number of effectively-CCW loops on the surface. // vLoopEffectivelyCCW : per-loop &quot;effectively CCW on the surface&quot; flags (size uiLoopCount); only // consulted in the unknown-index orientation fallback. // vLoopCoedgeCount : per-loop coedge count (size uiLoopCount), used to report the outer loop&#x27;s // edgeuse count. BrepStatus PlanFaceOuterLoop( uint32_t uiLoopCount, uint32_t uiSourceOuterLoopIndex, bool bClosedSurface, bool bAllLoopsCW, uint32_t uiCCWLoopCount, const std::vector&lt;bool&gt;&amp; vLoopEffectivelyCCW, const std::vector&lt;uint32_t&gt;&amp; vLoopCoedgeCount, SourceFaceOuterLoopData&amp; rOuterLoopData ); struct StagedFacePlanningResult { bool bMarkStandaloneImpliedLoopProcessed = false; bool bSetStandaloneImpliedOuterLoopEdgeuseCount = false; bool bExtractImpliedBoundaryEdges = false; bool bAddStandaloneImpliedBoundaryLoop = false; bool bMarkShellHasAugmentedFace = false; bool bFlipPriorFaceuseOrientationsForAugmentedFace = false; bool bSetAugmentedOuterLoopForCurrentFace = false; bool bSetCCWLoopAsExplicitOuterLoop = false; uint32_t uiCCWLoopExplicitOuterSourceLoopIndex = kStagedNoObjectIndex; uint32_t uiSelectedBoundarySourceLoopCoedgeCount = 0; bool bLoopCountChanged = false; uint32_t uiLoopCount = 0; }; class StagedFaceTraversalPlanner { public: StagedFaceTraversalPlanner(BrepStagingState&amp; rState, const SourceFaceData&amp; rSourceFaceData, uint32_t uiFaceIndex); BrepStatus PlanCurrentFace( uint32_t&amp; rLoopCount, const SourceFaceBoundaryContactData&amp; rBoundaryContactData, StagedFacePlanningResult&amp; rPlanningResult ); private: void ResetImpliedBoundaryState(); void SetImpliedBoundaryCase(uint32_t uiTouchingCWCount, uint32_t uiTouchingCCWCount); bool IsImpliedBoundaryCase(ImpliedBoundaryCase eCase) const; bool NeedsImpliedBoundaryEdges() const; void SetImpliedBoundaryAugmentTarget(uint32_t uiSourceLoopIndex, uint32_t uiContactVertexIndex); void SetCurrentFaceLoopCount(uint32_t uiLoopCount); BrepStagingState&amp; m_rState; const SourceFaceData&amp; m_rSourceFaceData; uint32_t m_uiFaceIndex = 0; }; #endif // BREP_FACE_TRAVERSAL_PLANNER_H", "keywords": []}, {"id": 3349, "doc_id": 3349, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepNaturalBoundaryBuilder.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepNaturalBoundaryBuilder.h", "display_name": "BrepNaturalBoundaryBuilder.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepNaturalBoundaryBuilder.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepNaturalBoundaryBuilder.h File members: BREP_STAGING/inc/BrepNaturalBoundaryBuilder.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_NATURAL_BOUNDARY_BUILDER_H #define BREP_NATURAL_BOUNDARY_BUILDER_H #include &quot;BrepEdgeVertexBuilder.h&quot; #include &quot;BrepSourceData.h&quot; #include &quot;BrepStatus.h&quot; #include &quot;BrepTopologyBuilder.h&quot; class NaturalBoundaryBuilder { public: NaturalBoundaryBuilder( BrepStagingState&amp; rState, StagedBrepEdgeVertexBuilder sEdgeVertexBuilder, StagedBrepTopologyBuilder sTopologyBuilder, uint32_t uiAugmentedOuterLoopEdgeuseCount, uint32_t uiOuterLoopEdgeuseStartIndex ); BrepStatus ExtractNaturalBoundaryDataForCurrentFace(SourceNaturalBoundaryData&amp; rBoundaryData); void ApplyNaturalBoundaryData(const SourceNaturalBoundaryData&amp; rBoundaryData); BrepStatus ExtractImpliedBoundaryEdgesForCurrentFace( const SourceNaturalBoundaryVertexResolver&amp; rFindExistingBoundaryVertex, uint32_t uiContactVertexIndex ); BrepStatus AddImpliedNaturalBoundaryAsLoopForCurrentFace(); BrepStatus AddImpliedNaturalBoundaryToLoop(); private: BrepStatus extractNaturalBoundaryVertexPositions(StagedSurfaceData&amp; rSurfaceData); BrepStatus extractImpliedBoundaryEdges( const SourceNaturalBoundaryVertexResolver&amp; rFindExistingBoundaryVertex, StagedSurfaceData&amp; rSurfaceData, uint32_t uiContactVertexIndex ); BrepStatus addImpliedNaturalBoundaryAsLoop(); StagedFaceData* GetCurrentStagedFace(); const StagedFaceData* GetCurrentStagedFace() const; pxr::GfRange2d GetCurrentStagedFaceDomain() const; StagedSurfaceData* GetCurrentStagedFaceSurface(); StagedEdgeuseData GetStagedEdgeuse(uint32_t uiEdgeuseIndex) const; uint32_t GetStagedEdgeuseEdgeIndex(uint32_t uiEdgeuseIndex) const; uint32_t GetStagedEdgeuseNextRadialIndex(uint32_t uiEdgeuseIndex) const; uint32_t GetStagedEdgeuseEndVertexIndex(uint32_t uiEdgeuseIndex) const; uint32_t GetStagedImpliedBoundarySegmentEdgeIndex(uint32_t uiSegmentIndex) const; void SetStagedEdgeuse(uint32_t uiEdgeuseIndex, const StagedEdgeuseData&amp; rEdgeuseData); void SetStagedEdgeuseNextRadialIndex(uint32_t uiEdgeuseIndex, uint32_t uiNextRadialEdgeuseIndex); StagedBrepEdgeVertexBuilder m_sEdgeVertexBuilder; StagedBrepTopologyBuilder m_sTopologyBuilder; BrepStagingState&amp; m_rState; uint32_t m_uiAugmentedOuterLoopEdgeuseCount = 0; uint32_t m_uiOuterLoopEdgeuseStartIndex = 0; }; #endif // BREP_NATURAL_BOUNDARY_BUILDER_H", "keywords": []}, {"id": 3350, "doc_id": 3350, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepSourceData.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepSourceData.h", "display_name": "BrepSourceData.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepSourceData.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepSourceData.h File members: BREP_STAGING/inc/BrepSourceData.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_SOURCE_DATA_H #define BREP_SOURCE_DATA_H #include &quot;BrepStagingState.h&quot; #include &quot;UsdBrepHeaders.h&quot; // pxr warning-suppression guard; keep ahead of &lt;pxr/..&gt; includes #include &lt;pxr/base/gf/range1d.h&gt; #include &lt;pxr/base/gf/range2d.h&gt; #include &lt;pxr/base/gf/vec3d.h&gt; #include &lt;cstdint&gt; #include &lt;functional&gt; #include &lt;vector&gt; struct SourceBrepData { double dTolerance = 0.0; uint32_t uiConnectedComponentCount = 0; uint32_t uiInfiniteRegionFaceuseCount = 0; }; struct SourceConnectedComponentTopologyReserveData { uint32_t uiShellBlockSize = 0; uint32_t uiFaceuseBlockSize = 0; uint32_t uiShellPairedSpacingIncrement = 0; uint32_t uiFaceusePairedSpacingIncrement = 0; }; struct SourceShellData { uint32_t uiFaceCount = 0; bool bClosed = false; }; struct SourceFaceData { uint32_t uiLoopCount = 0; uint32_t uiOuterLoopIndex = kStagedNoObjectIndex; bool bSameOrientationWithShell = true; bool bClosedSurface = false; bool bAllLoopsCW = false; uint32_t uiCCWLoopCount = 0; bool bHasImpliedNaturalBoundary = false; pxr::GfRange2d sDomain; }; struct SourceFaceOuterLoopData { uint32_t uiLoopCount = 0; uint32_t uiOuterLoopIndex = kStagedNoObjectIndex; uint32_t uiOuterLoopEdgeuseCount = 0; bool bHasImpliedNaturalBoundary = false; bool bExplicitOuterLoopOutOfRange = false; }; struct SourceLoopData { uint32_t uiCoedgeCount = 0; bool bSameOrientationWithSurface = true; }; struct SourceCoedgeData { uint32_t uiSourceEdgeIndex = kStagedNoObjectIndex; bool bSameOrientationWithLoop = true; }; struct SourceVertexData { uint32_t uiSourceVertexIndex = kStagedNoObjectIndex; pxr::GfVec3d sPoint; bool bHasPoint = false; }; struct SourceCurveData { StagedCurveData sCurveData; pxr::GfRange1d sInterval; }; struct SourceEdgeData { uint32_t uiSourceEdgeIndex = kStagedNoObjectIndex; uint32_t uiStartSourceVertexIndex = kStagedNoObjectIndex; uint32_t uiEndSourceVertexIndex = kStagedNoObjectIndex; SourceCurveData sCurve; }; struct SourceSurfaceData { StagedSurfaceData sSurfaceData; pxr::GfRange2d sDomain; }; struct SourceLoopBoundaryContactData { uint32_t uiLoopIndex = kStagedNoObjectIndex; uint32_t uiCoedgeCount = 0; bool bClockwiseWithSurface = false; bool bTouchesNaturalBoundary = false; uint32_t uiFirstContactStagedVertexIndex = kStagedNoObjectIndex; }; struct SourceFaceBoundaryContactData { std::vector&lt;SourceLoopBoundaryContactData&gt; vLoops; }; struct SourceNaturalBoundaryData { StagedSurfaceData sSurfaceData; pxr::GfRange2d sDomain; std::vector&lt;pxr::GfVec3d&gt; vBoundaryVertexPositions; }; using SourceNaturalBoundaryVertexResolver = std::function&lt;uint32_t(const pxr::GfVec3d&amp; rPoint)&gt;; #endif // BREP_SOURCE_DATA_H", "keywords": []}, {"id": 3351, "doc_id": 3351, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepStagingBuilder.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepStagingBuilder.h", "display_name": "BrepStagingBuilder.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepStagingBuilder.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepStagingBuilder.h File members: BREP_STAGING/inc/BrepStagingBuilder.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_STAGING_BUILDER_H #define BREP_STAGING_BUILDER_H #include &quot;BrepSourceData.h&quot; class GenericBrepStagingBuilder { public: explicit GenericBrepStagingBuilder(BrepStagingState&amp; rState); void ResetForSourceBrep(const SourceBrepData&amp; rBrepData); uint32_t AddFace(const SourceFaceData&amp; rFaceData, uint32_t uiLoopCount, StagedTrimType eTrimType); uint32_t AddFaceSurface(const SourceSurfaceData&amp; rSurfaceData); uint32_t AddFaceSurfaceForCurrentFace(const SourceSurfaceData&amp; rSurfaceData, StagedTrimType eTrimType); void SetCurrentFaceTrimAndDomain(StagedTrimType eTrimType, const pxr::GfRange2d&amp; rUVDomain); void SetCurrentFaceLoopCount(uint32_t uiLoopCount); void AddLoopForCurrentTraversal( const StagedLoopData&amp; rLoopData, bool bIsOuterLoop, uint32_t uiCurrentLoopTraversalCount, bool bHasStagedImpliedNaturalBoundary ); void AddSourceLoopForCurrentTraversal( const SourceLoopData&amp; rLoopData, bool bIsAugmentedOuterLoop, uint32_t uiAugmentedOuterLoopEdgeuseCount, bool bIsOuterLoop, uint32_t uiCurrentLoopTraversalCount, bool bHasStagedImpliedNaturalBoundary ); private: StagedFaceData* GetCurrentFace(); BrepStagingState&amp; m_rState; }; #endif // BREP_STAGING_BUILDER_H", "keywords": []}, {"id": 3352, "doc_id": 3352, "filename": "api/program_listing_file_BREP_STAGING_inc_BrepStagingState.h.html", "domain_name": "std", "name": "api/program_listing_file_BREP_STAGING_inc_BrepStagingState.h", "display_name": "BrepStagingState.h", "type": "doc", "display_type": "Page", "docname": "api/program_listing_file_BREP_STAGING_inc_BrepStagingState.h", "anchor": "", "priority": -1, "content": "Fully qualified name: BREP_STAGING/inc/BrepStagingState.h File members: BREP_STAGING/inc/BrepStagingState.h // SPDX-FileCopyrightText: Copyright (c) 2026 NVIDIA CORPORATION &amp; AFFILIATES. All rights reserved. // SPDX-License-Identifier: Apache-2.0 #ifndef BREP_STAGING_STATE_H #define BREP_STAGING_STATE_H #include &quot;UsdBrepHeaders.h&quot; // pxr warning-suppression guard; keep ahead of &lt;pxr/..&gt; includes #include &lt;pxr/base/gf/range1d.h&gt; #include &lt;pxr/base/gf/range2d.h&gt; #include &lt;pxr/base/gf/range3d.h&gt; #include &lt;pxr/base/gf/vec2d.h&gt; #include &lt;pxr/base/gf/vec3d.h&gt; #include &lt;pxr/base/vt/array.h&gt; #include &lt;cstdint&gt; #include &lt;map&gt; #include &lt;vector&gt; using SourceObjectId = uintptr_t; enum class StagedRegionType { Solid, Void }; struct StagedRegionData { uint32_t uiShellCount = 0; StagedRegionType eRegionType = StagedRegionType::Void; }; enum class StagedShellPointType { None, VertexPoint }; struct StagedShellData { uint32_t uiFaceuseCount = 0; uint32_t uiWireEdgeCount = 0; StagedShellPointType eShellPointType = StagedShellPointType::None; }; enum class StagedOrientType { NotSet, Same, Opposite }; // Matches USDBREP_NO_OBJECT_INDEX in UsdBrepArrayData.h; kept below UINT32_MAX for debug visibility. static constexpr uint32_t kStagedNoObjectIndex = 9999999U; struct StagedFaceuseData { uint32_t uiFaceIndex = kStagedNoObjectIndex; StagedOrientType eOrientType = StagedOrientType::NotSet; }; enum class StagedRadialEntryType { NotSet, TopSideEntry, BottomSideEntry }; struct StagedEdgeuseData { uint32_t uiEdgeIndex = kStagedNoObjectIndex; StagedOrientType eOrientType = StagedOrientType::NotSet; uint32_t uiNextRadialEdgeuseIndex = kStagedNoObjectIndex; StagedRadialEntryType eEntrySideType = StagedRadialEntryType::NotSet; }; enum class StagedCurveType { NotSet, NoObject, BSplineCurve, Line, Circle, Ellipse }; struct StagedEdgeData { StagedCurveType eCurveType = StagedCurveType::NotSet; pxr::GfRange1d sInterval; uint32_t uiStartVertexIndex = kStagedNoObjectIndex; uint32_t uiEndVertexIndex = kStagedNoObjectIndex; }; struct StagedCurveData { StagedCurveType eCurveType = StagedCurveType::NotSet; pxr::VtArray&lt;pxr::GfVec3d&gt; vNurbControlVertices; uint32_t uiNurbVertexCount = 0; uint32_t uiNurbOrder = 0; pxr::VtArray&lt;double&gt; vNurbKnots; pxr::VtArray&lt;double&gt; vNurbWeights; pxr::GfVec3d sOrigin; pxr::GfVec3d sDirection; pxr::GfVec3d sCenter; pxr::GfVec3d sAxis; pxr::GfVec3d sRefDirection; double dRadius = 0.0; double dXRadius = 0.0; double dYRadius = 0.0; }; // Parameter-space (UV) trim curve attached to a single edgeuse. Required to disambiguate the two // uses of a seam edge on a closed/periodic surface (one at U=Umin, one at U=Umax): without it a // tessellator that recomputes the trim from the shared 3D seam curve maps both uses to the same // side and collapses the parameter rectangle. Stored as a 2D NURBS (flat clamped knots), mirroring // the BrepCurveUvNurbAPI schema. An invalid record means &quot;no UV curve&quot; (the placeholder is emitted). // Store in edgeuse traversal order: opposite edgeuses run against the 3D edge direction. struct StagedCurveData2d { bool bValid = false; uint32_t uiNurbVertexCount = 0; uint32_t uiNurbOrder = 0; pxr::VtArray&lt;pxr::GfVec2d&gt; vNurbControlVertices; pxr::VtArray&lt;double&gt; vNurbKnots; pxr::VtArray&lt;double&gt; vNurbWeights; }; struct StagedLoopData { uint32_t uiEdgeuseCount = 0; uint32_t uiVertexIndex = kStagedNoObjectIndex; }; enum class StagedVertexType { NotSet, None, VertexPoint }; struct StagedVertexData { StagedVertexType eVertexType = StagedVertexType::NotSet; }; enum class StagedSurfaceType { NotSet, BSplineSurface, Plane, Cylinder, Cone, Sphere, Torus }; enum class StagedTrimType { NotSet, Rectangular, General }; struct StagedFaceData { uint32_t uiLoopCount = 0; StagedSurfaceType eSurfaceType = StagedSurfaceType::NotSet; StagedTrimType eTrimType = StagedTrimType::NotSet; pxr::GfRange2d sUVDomain; }; struct StagedSurfaceData { StagedSurfaceType eSurfaceType = StagedSurfaceType::NotSet; pxr::VtArray&lt;pxr::GfVec3d&gt; vNurbControlVertices; uint32_t uiNurbUVertexCount = 0; uint32_t uiNurbVVertexCount = 0; uint32_t uiNurbUOrder = 0; uint32_t uiNurbVOrder = 0; pxr::VtArray&lt;double&gt; vNurbUKnots; pxr::VtArray&lt;double&gt; vNurbVKnots; pxr::VtArray&lt;double&gt; vNurbWeights; pxr::GfVec3d sOrigin; pxr::GfVec3d sCenter; pxr::GfVec3d sAxis; pxr::GfVec3d sRefDirection; double dRadius = 0.0; double dSemiAngle = 0.0; double dMajorRadius = 0.0; double dMinorRadius = 0.0; }; struct StagedBrepData { double dTolerance = 0.0; pxr::GfRange3d sExtent; std::vector&lt;StagedRegionData&gt; vRegions; std::vector&lt;StagedShellData&gt; vShells; std::vector&lt;StagedFaceuseData&gt; vFaceuses; std::vector&lt;StagedEdgeuseData&gt; vEdgeuses; std::vector&lt;StagedEdgeData&gt; vEdges; std::vector&lt;StagedEdgeData&gt; vWireEdges; std::vector&lt;StagedCurveData&gt; vEdgeCurves; std::vector&lt;StagedCurveData&gt; vWireEdgeCurves; std::vector&lt;StagedLoopData&gt; vLoops; std::vector&lt;StagedVertexData&gt; vVertices; std::vector&lt;pxr::GfVec3d&gt; vShellPoints; std::vector&lt;pxr::GfVec3d&gt; vVertexPoints; std::vector&lt;StagedFaceData&gt; vFaces; std::vector&lt;StagedSurfaceData&gt; vFaceSurfaces; // UV trim curves keyed by staged edgeuse index (sparse: only edgeuses that carry one). std::map&lt;uint32_t, StagedCurveData2d&gt; mEdgeuseCurve2d; void ClearCollections() { vRegions.clear(); vShells.clear(); vFaceuses.clear(); vEdgeuses.clear(); vEdges.clear(); vWireEdges.clear(); vEdgeCurves.clear(); vWireEdgeCurves.clear(); vLoops.clear(); vVertices.clear(); vShellPoints.clear(); vVertexPoints.clear(); vFaces.clear(); vFaceSurfaces.clear(); mEdgeuseCurve2d.clear(); } }; struct StagedEdgeRadialValues { uint32_t uiRadialHead_EUIndex = kStagedNoObjectIndex; uint32_t uiRadialTail_EUIndex = kStagedNoObjectIndex; }; // Boundary merge case classification enum ImpliedBoundaryCase { BoundaryCase_None = 0, // face does not need boundary work BoundaryCase_StandaloneLoop, // Case 1: no loops touch boundary \u2014 add standalone CCW outer loop BoundaryCase_AugmentCWLoop, // Case 2: one CW loop touches boundary \u2014 augment it with boundary edges BoundaryCase_CCWLoopIsOuter, // Case 3: one CCW loop touches boundary \u2014 it is already the outer loop BoundaryCase_MultiCWMerge, // Case 4: multiple CW loops touch boundary \u2014 merge into one CCW outer BoundaryCase_MixedError // Case 5: mixed CW/CCW touch boundary \u2014 error }; class BrepStagingState { public: StagedBrepData&amp; Data() { return m_sData; } const StagedBrepData&amp; Data() const { return m_sData; } void ClearCollections() { m_sData.ClearCollections(); } void Clear() { ClearCollections(); ClearDedupMaps(); ClearImpliedBoundarySegments(); ClearNaturalBoundaryVertexPositions(); ResetImpliedBoundaryState(); } double GetTolerance() const { return m_sData.dTolerance; } void SetTolerance(double dTolerance) { m_sData.dTolerance = dTolerance; } pxr::GfRange3d GetExtent() const { return m_sData.sExtent; } void SetExtent(const pxr::GfVec3d&amp; rMin, const pxr::GfVec3d&amp; rMax) { m_sData.sExtent.SetMin(rMin); m_sData.sExtent.SetMax(rMax); } uint32_t GetRegionCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vRegions.size()); } void ResizeRegionRecords(uint32_t uiRegionCount) { m_sData.vRegions.resize(uiRegionCount); } StagedRegionData* GetRegionRecord(uint32_t uiRegionIndex) { return uiRegionIndex &lt; GetRegionCount() ? &amp;m_sData.vRegions[uiRegionIndex] : nullptr; } const StagedRegionData* GetRegionRecord(uint32_t uiRegionIndex) const { return uiRegionIndex &lt; GetRegionCount() ? &amp;m_sData.vRegions[uiRegionIndex] : nullptr; } uint32_t AddRegionRecord(const StagedRegionData&amp; rRegionData) { m_sData.vRegions.push_back(rRegionData); return GetRegionCount() - 1; } uint32_t GetShellCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vShells.size()); } void ResizeShellRecords(uint32_t uiShellCount) { m_sData.vShells.resize(uiShellCount); } StagedShellData* GetShellRecord(uint32_t uiShellIndex) { return uiShellIndex &lt; GetShellCount() ? &amp;m_sData.vShells[uiShellIndex] : nullptr; } const StagedShellData* GetShellRecord(uint32_t uiShellIndex) const { return uiShellIndex &lt; GetShellCount() ? &amp;m_sData.vShells[uiShellIndex] : nullptr; } bool TryGetShellPoint(uint32_t uiShellPointIndex, pxr::GfVec3d&amp; rPoint) const { if (uiShellPointIndex &gt;= m_sData.vShellPoints.size()) { return false; } rPoint = m_sData.vShellPoints[uiShellPointIndex]; return true; } uint32_t GetFaceuseCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vFaceuses.size()); } void ResizeFaceuseRecords(uint32_t uiFaceuseCount) { m_sData.vFaceuses.resize(uiFaceuseCount); } StagedFaceuseData* GetFaceuseRecord(uint32_t uiFaceuseIndex) { return uiFaceuseIndex &lt; GetFaceuseCount() ? &amp;m_sData.vFaceuses[uiFaceuseIndex] : nullptr; } const StagedFaceuseData* GetFaceuseRecord(uint32_t uiFaceuseIndex) const { return uiFaceuseIndex &lt; GetFaceuseCount() ? &amp;m_sData.vFaceuses[uiFaceuseIndex] : nullptr; } uint32_t GetFaceCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vFaces.size()); } StagedFaceData* GetFaceRecord(uint32_t uiFaceIndex) { return uiFaceIndex &lt; GetFaceCount() ? &amp;m_sData.vFaces[uiFaceIndex] : nullptr; } const StagedFaceData* GetFaceRecord(uint32_t uiFaceIndex) const { return uiFaceIndex &lt; GetFaceCount() ? &amp;m_sData.vFaces[uiFaceIndex] : nullptr; } void AppendFaceRecord(const StagedFaceData&amp; rFaceData) { m_sData.vFaces.push_back(rFaceData); } uint32_t GetFaceSurfaceCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vFaceSurfaces.size()); } StagedSurfaceData* GetFaceSurfaceRecord(uint32_t uiSurfaceIndex) { return uiSurfaceIndex &lt; GetFaceSurfaceCount() ? &amp;m_sData.vFaceSurfaces[uiSurfaceIndex] : nullptr; } const StagedSurfaceData* GetFaceSurfaceRecord(uint32_t uiSurfaceIndex) const { return uiSurfaceIndex &lt; GetFaceSurfaceCount() ? &amp;m_sData.vFaceSurfaces[uiSurfaceIndex] : nullptr; } void AppendFaceSurfaceRecord(const StagedSurfaceData&amp; rSurfaceData) { m_sData.vFaceSurfaces.push_back(rSurfaceData); } uint32_t GetLoopCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vLoops.size()); } StagedLoopData* GetLoopRecord(uint32_t uiLoopIndex) { return uiLoopIndex &lt; GetLoopCount() ? &amp;m_sData.vLoops[uiLoopIndex] : nullptr; } const StagedLoopData* GetLoopRecord(uint32_t uiLoopIndex) const { return uiLoopIndex &lt; GetLoopCount() ? &amp;m_sData.vLoops[uiLoopIndex] : nullptr; } void AppendLoopRecord(const StagedLoopData&amp; rLoopData) { m_sData.vLoops.push_back(rLoopData); } void InsertLoopRecordAt(uint32_t uiIndex, const StagedLoopData&amp; rLoopData) { m_sData.vLoops.insert(m_sData.vLoops.begin() + uiIndex, rLoopData); } uint32_t GetEdgeuseCount() const { return static_cast&lt;uint32_t&gt;(m_sData.vEdgeuses.size()); } void ResizeEdgeuseRecords(uint32_t uiEdgeuseCount) { m_sData.vEdgeuses.resize(uiEdgeuseCount); } StagedEdgeuseData* GetEdgeuseRecord(uint32_t uiEdgeuseIndex) { return uiEdgeuseIndex &lt; GetEdgeuseCount() ? &amp;m_sData.vEdgeuses[uiEdgeuseIndex] : nullptr; } const StagedEdgeuseData* GetEdgeuseRecord(uint32_t uiEdgeuseIndex) const { return uiEdgeuseIndex &lt; GetEdgeuseCount() ? &amp;m_sData.vEdgeuses[uiEdgeuseIndex] : nullptr; } void AppendEdgeuseRecord(const StagedEdgeuseData&amp; rEdgeuseData) { m_sData.vEdgeuses.push_back(rEdgeuseData); } void SetEdgeuseCurve2d(uint32_t uiEdgeuseIndex, const StagedCurveData2d&amp; rCurve) { m_sData.mEdgeuseCurve2d[uiEdgeuseIndex] = rCurve; } const StagedCurveData2d* GetEdgeuseCurve2d(uint32_t uiEdgeuseIndex) const { const auto sIter = m_sData.mEdgeuseCurve2d.find(uiEdgeuseIndex); return sIter != m_